function evaluateProperty({api, helpers}) {
function camelToDisplayText(str) {
  return str.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/^./, match => match.toUpperCase());
}
  var data = api.data.sam_properties_1.output.properties;
  console.log("data ",api.data.sam_properties_1.output.properties)

  var modifiedData = data.map((e)=>{
    return {
      "id" : e.property,
      "label" : e.property,
      "sublabel" : e.name
    };
  });
  console.log(data,modifiedData);
	return modifiedData;
}
